<?php if (!defined('ABSPATH')) exit; $bid=(int)$bolao->id; if(isset($_POST['rsb_result']) && check_admin_referer('rsb_result')){ RSB_Jogos::set_result((int)$_POST['jogo_id'], (int)$_POST['gols_mandante'], (int)$_POST['gols_visitante']); echo '<div class="notice notice-success"><p>Resultado lançado, pontuação recalculada e confrontos futuros verificados.</p></div>'; } $jogos=RSB_Jogos::all($bid); if(isset($_GET['rsb_bracket'])){ $warnings=get_transient('rsb_bracket_notice_' . get_current_user_id()); delete_transient('rsb_bracket_notice_' . get_current_user_id()); echo '<div class="notice notice-success"><p>Confrontos futuros recalculados com segurança.</p></div>'; if($warnings){ echo '<div class="notice notice-warning"><p>'.esc_html(implode(' ', (array)$warnings)).'</p></div>'; } } ?>
<div class="wrap rsb-wrap"><h1>Resultados</h1><form method="post" class="rsb-inline"><?php wp_nonce_field('rsb_result'); ?><select name="jogo_id"><?php foreach($jogos as $j): ?><option value="<?php echo esc_attr($j->id); ?>"><?php echo esc_html($j->codigo_jogo.' — '.$j->time_mandante.' x '.$j->time_visitante); ?></option><?php endforeach; ?></select><input type="number" min="0" name="gols_mandante" placeholder="Gols 1"><input type="number" min="0" name="gols_visitante" placeholder="Gols 2"><button class="button button-primary" name="rsb_result" value="1">Salvar Resultado</button></form><p><a class="button" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=rsb_recalculate_bracket'), 'rsb_recalculate_bracket')); ?>">Recalcular confrontos futuros</a></p></div>
